// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address a1, address a2) public {
        vm.assume(a1 != a2);

        FactoryForTest factory = new FactoryForTest(address(c));

        address clone = factory.createCloneWithArgs(a1, a2);

        Cooler cloneC = Cooler(payable(clone));

        assertTrue(cloneC.owner() == a1);
    }
}

contract FactoryForTest {
    address implementation;
    constructor(address impl) {
        implementation = impl;
    }

    function createCloneWithArgs(address a1, address a2) external returns (address payable instance) {
        bytes memory data = abi.encodePacked(a1, a2, address(this));

        bytes memory creation;
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x3d602d80600a3d3981f3)
        }
        DeployedWithData d = new DeployedWithData(implementation, data);
        return payable(address(d));
    }
}

contract DeployedWithData {
    address impl;
    bytes internal immData;
    constructor(address _impl, bytes memory data) {
        impl = _impl;
        immData = data;
    }
    fallback() external payable {

        bytes memory callData = msg.data;
        bytes memory full = abi.encodePacked(callData, immData, bytes2(uint16(immData.length)));
        (bool ok, bytes memory ret) = impl.delegatecall(full);
        if (ok) assembly { return(add(ret, 32), mload(ret)) }
        else assembly { revert(add(ret, 32), mload(ret)) }
    }
}
